"""Tool Execution Node for executing tool calls generated by LLM Planner."""

from __future__ import annotations

import json
from typing import Any

import pandas as pd
from langchain_core.messages import AIMessage, BaseMessage, ToolMessage

from csv_analytics_agent.execution.exceptions import CapabilityNotFoundError
from csv_analytics_agent.execution.models import (
    ExecutionRequest,
    ExecutionResult,
    ExecutionStatus,
)
from csv_analytics_agent.execution.registry import CapabilityRegistry
from csv_analytics_agent.graph.state import AgentState, FilterPayload
from csv_analytics_agent.logging_config import get_logger

logger = get_logger(__name__)


def tool_node(
    state: AgentState,
    registry: CapabilityRegistry,
    dataframe: pd.DataFrame,
) -> dict[str, Any]:
    """LangGraph node executing tool calls generated by the LLM planner.

    Args:
        state: Active AgentState containing conversation messages and active_filters.
        registry: CapabilityRegistry instance containing registered domain engines.
        dataframe: Target dataset pandas DataFrame context.

    Returns:
        Partial AgentState dictionary update containing emitted ToolMessages, last_result,
        and updated active_filters if dataset filter capabilities were executed.
    """
    messages: list[BaseMessage] = state.get("messages", [])
    if not messages:
        return {}

    # Find the latest AIMessage with tool calls
    last_ai_msg: AIMessage | None = None
    for msg in reversed(messages):
        if isinstance(msg, AIMessage) and getattr(msg, "tool_calls", None):
            last_ai_msg = msg
            break

    if not last_ai_msg or not last_ai_msg.tool_calls:
        return {}

    tool_messages: list[ToolMessage] = []
    last_result: ExecutionResult[Any] | None = None
    active_filters: list[FilterPayload] = list(state.get("active_filters", []))

    # Execute requested tool calls sequentially preserving order
    for call in last_ai_msg.tool_calls:
        call_id = str(call.get("id", "call_unknown"))
        cap_name = str(call.get("name", ""))
        args = dict(call.get("args", {}))

        target_columns = list(args.get("target_columns", []))
        parameters = dict(args.get("parameters", {}))

        # Handle top-level argument payload parameters if nested 'parameters' is omitted
        for k, v in args.items():
            if k not in ("target_columns", "parameters"):
                parameters[k] = v

        try:
            engine = registry.get_engine(cap_name)
            # Inject profile from state into context_metadata so
            # VisualizationProvider.execute() can access it for recommend_visualization.
            context_metadata: dict[str, object] = {"raw_query": cap_name}
            profile = state.get("profile")
            if profile is not None:
                context_metadata["profile"] = profile
            request = ExecutionRequest(
                capability_name=cap_name,
                target_columns=target_columns,
                parameters=parameters,
                context_metadata=context_metadata,
            )
            exec_res = engine.execute_capability(request, dataframe)
        except CapabilityNotFoundError as err:
            logger.warning(
                "tool_call_failed",
                tool=cap_name,
                error_type="CapabilityNotFoundError",
                error=str(err),
            )
            exec_res = ExecutionResult(
                capability_name=cap_name,
                status=ExecutionStatus.FAILED,
                message=str(err),
                data=None,
            )
        except Exception as err:
            logger.warning(
                "tool_call_failed",
                tool=cap_name,
                error_type=type(err).__name__,
                error=str(err),
            )
            exec_res = ExecutionResult(
                capability_name=cap_name,
                status=ExecutionStatus.FAILED,
                message=f"Execution exception: {err}",
                data=None,
            )

        last_result = exec_res
        logger.info(
            "tool_call_result",
            tool=cap_name,
            status=exec_res.status.value,
            success=exec_res.status == ExecutionStatus.SUCCESS,
        )

        # Serialize result payload for ToolMessage content
        tool_content = json.dumps(
            {
                "capability": exec_res.capability_name,
                "status": exec_res.status.value,
                "message": exec_res.message,
                "data": str(exec_res.data),
            }
        )

        tool_msg = ToolMessage(content=tool_content, tool_call_id=call_id)
        tool_messages.append(tool_msg)

        # Update active_filters if filter capability succeeded
        if cap_name == "filter" and exec_res.status == ExecutionStatus.SUCCESS:
            filter_item: FilterPayload = {
                "capability": "filter",
                "target_columns": target_columns,
                "parameters": str(parameters),
            }
            active_filters.append(filter_item)

    state_update: dict[str, Any] = {
        "messages": tool_messages,
        "last_result": last_result,
        "active_filters": active_filters,
    }
    return state_update


__all__ = ["tool_node"]
